// Pseudo: bounded per-tenant backpressure
function handleEvent(event, tenant) {
  const q = queues[tenant];
  if (q.length < MAX_PER_TENANT) {
    enqueue(event, tenant);
  } else {
    drop(event); // apply backpressure upstream
  }
}
```

